:root {
  color: #172033;
  background: #f8fafc;
  font-family:
    Inter,
    ui-sans-serif,
    system-ui,
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
}

a {
  color: inherit;
}

.app-shell {
  min-height: 100vh;
}

.app-shell nav {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1rem;
  padding: 1.5rem clamp(2rem, 6vw, 5rem);
  border-bottom: 1px solid #d6dde7;
}

.app-shell nav ul {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.home {
  display: grid;
  min-height: 100vh;
  align-content: center;
  gap: 1.5rem;
  padding: clamp(2rem, 6vw, 5rem);
}

.skip-link {
  position: absolute;
  top: 0.5rem;
  left: 0.5rem;
  transform: translateY(-150%);
  background: #ffffff;
  padding: 0.75rem;
}

.skip-link:focus {
  transform: translateY(0);
}

.home form {
  display: grid;
  gap: 1.25rem;
  width: min(100%, 32rem);
}

.home form label {
  display: grid;
  gap: 0.5rem;
}

.home form label:has(input[type="checkbox"]) {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.home input:not([type="checkbox"]),
.home select,
.home button {
  min-height: 2.75rem;
  border: 1px solid #94a3b8;
  border-radius: 0.375rem;
  background: #ffffff;
  padding: 0.625rem 0.75rem;
  color: inherit;
  font: inherit;
}

.home input[type="checkbox"] {
  width: 1.25rem;
  height: 1.25rem;
  margin: 0;
}

.home button {
  justify-self: start;
  background: #172033;
  color: #ffffff;
  cursor: pointer;
}

.home button:disabled {
  opacity: 0.7;
}

a:focus-visible,
.home input:focus-visible,
.home select:focus-visible,
.home button:focus-visible {
  outline: 3px solid #2563eb;
  outline-offset: 0.25rem;
}

.home h1 {
  margin: 0;
  max-width: 14ch;
  font-size: clamp(3rem, 8vw, 7rem);
  line-height: 0.95;
}

.home p {
  margin: 0;
  max-width: 42rem;
  color: #526071;
  font-size: 1.125rem;
  line-height: 1.7;
}

.home code {
  border: 1px solid #d6dde7;
  border-radius: 6px;
  background: #ffffff;
  padding: 0.15rem 0.35rem;
}

.home output {
  display: grid;
  gap: 0.5rem;
  font-size: 1.125rem;
  line-height: 1.7;
}

.calculation-details {
  max-width: 42rem;
  border: 1px solid #d6dde7;
  border-radius: 0.5rem;
  background: #ffffff;
  padding: 1rem;
}

.calculation-details summary {
  cursor: pointer;
  font-weight: 600;
}

.calculation-details summary:focus-visible {
  outline: 3px solid #2563eb;
  outline-offset: 0.25rem;
}

.calculation-details dl > div {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 0.5rem 1.5rem;
  padding-block: 0.5rem;
  border-bottom: 1px solid #d6dde7;
}

.calculation-details dd {
  margin: 0;
  font-variant-numeric: tabular-nums;
}

.calculation-details li {
  line-height: 1.7;
}

.docs-layout {
  display: grid;
  grid-template-columns: 17rem minmax(0, 1fr);
  align-items: start;
  gap: clamp(2rem, 4vw, 4rem);
  max-width: 86rem;
  margin-inline: auto;
  padding: 2.5rem clamp(1.25rem, 4vw, 4rem);
}

.docs-sidebar {
  position: sticky;
  top: 1rem;
}

.docs-navigation-panel summary {
  padding-block: 0.5rem;
  font-weight: 600;
  cursor: pointer;
}

.app-shell .docs-navigation {
  display: block;
  max-height: 70vh;
  overflow-y: auto;
  border: 0;
  padding: 0.75rem 0.75rem 0 0;
  font-size: 0.9375rem;
  line-height: 1.5;
}

.docs-navigation section + section {
  margin-top: 1.5rem;
}

.docs-navigation section > a {
  display: inline-block;
  font-weight: 600;
}

.app-shell .docs-navigation ul {
  display: grid;
  gap: 0.25rem;
  padding: 0.5rem 0 0;
}

.docs-navigation li a {
  display: block;
  padding: 0.25rem 0.5rem;
  color: #526071;
  text-decoration: none;
}

.docs-navigation a[aria-current="page"] {
  color: #172033;
  font-weight: 600;
  text-decoration: underline;
  text-underline-offset: 0.25em;
}

.docs-navigation a:hover {
  color: #172033;
  text-decoration: underline;
  text-underline-offset: 0.25em;
}

.docs-article {
  min-width: 0;
  max-width: 72ch;
  font-size: 1.0625rem;
  line-height: 1.75;
}

.docs-article h1 {
  margin: 0 0 1.5rem;
  font-size: clamp(2rem, 4vw, 3rem);
  line-height: 1.15;
  text-wrap: balance;
}

.docs-article h2,
.docs-article h3 {
  margin-top: 2.5rem;
  margin-bottom: 0.75rem;
  line-height: 1.3;
  text-wrap: balance;
}

.docs-article a {
  color: #075985;
  text-underline-offset: 0.2em;
}

.docs-article figure {
  margin: 1.5rem 0;
}

.docs-article figcaption {
  border-bottom: 1px solid #d6dde7;
  padding: 0.5rem 0.75rem;
  font-size: 0.875rem;
}

.docs-article pre {
  max-width: 100%;
  overflow-x: auto;
  border: 1px solid #d6dde7;
  border-radius: 0.375rem;
  padding: 1rem;
  font-size: 0.875rem;
  line-height: 1.6;
}

.docs-table-scroll {
  max-width: 100%;
  overflow-x: auto;
}

.docs-article table {
  border-collapse: collapse;
  font-size: 0.9375rem;
}

.docs-article th,
.docs-article td {
  border: 1px solid #d6dde7;
  padding: 0.625rem 0.75rem;
  text-align: left;
}

.docs-article img,
.docs-article svg {
  max-width: 100%;
  height: auto;
}

.docs-state {
  max-width: 72ch;
  margin: 3rem auto;
  padding: 1.5rem;
  line-height: 1.7;
}

.docs-navigation-panel summary:focus-visible,
.docs-table-scroll:focus-visible {
  outline: 3px solid #2563eb;
  outline-offset: 0.25rem;
}

@media (max-width: 52rem) {
  .docs-layout {
    display: block;
    padding-top: 1.5rem;
  }

  .docs-sidebar {
    position: static;
    margin-bottom: 2rem;
  }

  .app-shell .docs-navigation {
    max-height: 16rem;
  }
}

.docs-search-form {
  margin-block: 1.75rem 2.5rem;
}
.docs-search-form label {
  display: block;
  margin-bottom: 0.5rem;
  font-weight: 600;
}
.docs-search-controls {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
}
.docs-search-controls input,
.docs-search-controls button {
  min-height: 2.75rem;
  border: 1px solid #94a3b8;
  border-radius: 0.375rem;
  padding: 0.625rem 0.75rem;
  font: inherit;
  color: inherit;
  background: #fff;
}
.docs-search-controls input {
  flex: 1 1 15rem;
  min-width: 0;
  width: 100%;
}
.docs-search-controls button {
  background: #172033;
  color: #fff;
  cursor: pointer;
}
.docs-search-controls input:focus-visible,
.docs-search-controls button:focus-visible {
  outline: 3px solid #2563eb;
  outline-offset: 0.25rem;
}
.docs-search-form p {
  margin-top: 0.75rem;
  color: #526071;
  font-size: 0.9375rem;
}
.docs-search-results {
  list-style: none;
  padding: 0;
}
.docs-search-results li {
  margin-top: 2rem;
  padding-bottom: 1.75rem;
  border-bottom: 1px solid #d6dde7;
}
.docs-search-results h3 {
  margin: 0 0 0.5rem;
  font-size: 1.25rem;
}
.docs-search-results p {
  margin: 0.5rem 0;
}

