import { Link } from "@tanstack/react-router";
import type {
  DocsPublicNavigation,
  DocsPublicPage,
} from "@taxkit/content/schemas";
import { Array, Option } from "effect";

import { requestDocsNavigationFocus } from "./components";

export const DocsNavigation = ({
  currentPath,
  navigation,
}: {
  readonly currentPath: Option.Option<DocsPublicPage["path"]>;
  readonly navigation: DocsPublicNavigation;
}) => (
  <details className="docs-navigation-panel" open>
    <summary>Documentation navigation</summary>
    <Link onClick={requestDocsNavigationFocus} to="/search">
      Search documentation
    </Link>
    <nav aria-label="Documentation" className="docs-navigation">
      {Array.map(navigation.primaryNavigation, (section) => (
        <section key={section.path}>
          <Link
            activeOptions={{ exact: true }}
            aria-current={
              Option.contains(currentPath, section.path) ? "page" : undefined
            }
            onClick={requestDocsNavigationFocus}
            params={{ _splat: section.path.slice(1) }}
            to="/$"
          >
            {section.title}
          </Link>
          <ul>
            {Array.map(section.pages, (item) => (
              <li key={item.path}>
                <Link
                  activeOptions={{ exact: true }}
                  aria-current={
                    Option.contains(currentPath, item.path) ? "page" : undefined
                  }
                  onClick={requestDocsNavigationFocus}
                  params={{ _splat: item.path.slice(1) }}
                  to="/$"
                >
                  {item.title}
                </Link>
              </li>
            ))}
          </ul>
        </section>
      ))}
    </nav>
  </details>
);

export const DocsPageUnavailable = () => (
  <section className="docs-state" role="alert">
    <h1>Documentation could not load</h1>
    <p>Please reload this page to try again.</p>
    <a href="/start/quickstart">Open the Quickstart</a>
  </section>
);

export const DocsPageNotFound = () => (
  <section className="docs-state">
    <h1>Documentation page not found</h1>
    <p>Choose a page from the documentation navigation.</p>
    <a href="/start/quickstart">Open the Quickstart</a>
  </section>
);
import { Link, useLocation } from "@tanstack/react-router";
import { Picture, Pre } from "@taxkit/docs-fumadocs/render";
import type { ComponentPropsWithoutRef, MouseEvent } from "react";

const focusIntentAttribute = "data-docs-focus-heading";

// Focus is a local browser command shared by navigation and compiled MDX.
// Only ordinary route clicks record intent; hydration never does.
export const requestDocsNavigationFocus = (
  event: MouseEvent<HTMLAnchorElement>
) => {
  if (
    event.button === 0 &&
    !event.defaultPrevented &&
    !event.altKey &&
    !event.ctrlKey &&
    !event.metaKey &&
    !event.shiftKey
  ) {
    document.documentElement.setAttribute(focusIntentAttribute, "true");
  }
};

const DocsMdxLink = ({
  "aria-label": ariaLabel,
  children,
  download,
  href,
  ...props
}: Readonly<ComponentPropsWithoutRef<"a">>) => {
  const currentPath = useLocation({ select: (location) => location.pathname });
  if (
    href === undefined ||
    download !== undefined ||
    props.target !== undefined ||
    href.startsWith("#") ||
    href.startsWith("//") ||
    /^[a-z][a-z0-9+.-]*:/iu.test(href) ||
    !(
      href.startsWith("/") ||
      href.startsWith("?") ||
      /\.mdx(?=$|[?#])/u.test(href)
    )
  ) {
    return (
      <a
        {...props}
        {...(ariaLabel === undefined ? {} : { "aria-label": ariaLabel })}
        download={download}
        href={href}
      >
        {children}
      </a>
    );
  }
  // This inert base resolves authored relative links only. It is never a
  // request address, public origin or configuration fallback.
  const destination = new URL(
    href.replace(/\.mdx(?=$|[?#])/u, ""),
    `https://taxkit.invalid${currentPath}`
  );
  return (
    <Link
      {...(ariaLabel === undefined ? {} : { "aria-label": ariaLabel })}
      {...(props.className === undefined ? {} : { className: props.className })}
      {...(props.id === undefined ? {} : { id: props.id })}
      {...(props.title === undefined ? {} : { title: props.title })}
      onClick={(event) => {
        props.onClick?.(event);
        requestDocsNavigationFocus(event);
      }}
      to={`${destination.pathname}${destination.search}${destination.hash}`}
    >
      {children}
    </Link>
  );
};

export const DocsHeading = ({
  children,
  ...props
}: Readonly<ComponentPropsWithoutRef<"h1">>) => (
  <h1
    {...props}
    ref={(heading) => {
      if (
        heading !== null &&
        document.documentElement.getAttribute(focusIntentAttribute) === "true"
      ) {
        document.documentElement.removeAttribute(focusIntentAttribute);
        heading.focus();
      }
    }}
    tabIndex={-1}
  >
    {children}
  </h1>
);

/* oxlint-disable jsx-a11y/no-noninteractive-tabindex -- A labelled horizontal table scroll region needs explicit keyboard focus across supported browsers. */
const DocsMdxTable = ({
  children,
  ...props
}: Readonly<ComponentPropsWithoutRef<"table">>) => (
  <section
    aria-label="Documentation table"
    className="docs-table-scroll"
    tabIndex={0}
  >
    <table {...props}>{children}</table>
  </section>
);
/* oxlint-enable jsx-a11y/no-noninteractive-tabindex */

export const docsMdxComponents = {
  a: DocsMdxLink,
  h1: DocsHeading,
  img: Picture,
  pre: Pre,
  table: DocsMdxTable,
};

